const input = $input.all().map(i => i.json || {});
const rows = input
  .filter(r => r.active === true || String(r.active).toLowerCase() === 'true')
  .map(r => ({
    record_key: String(r.record_key || '').trim(),
    category: String(r.category || '').trim().toLowerCase(),
    sku: String(r.sku || '').trim(),
    name: String(r.name || '').trim(),
    price_project: Number(r.price_project || 0),
    price_monthly: Number(r.price_monthly || 0),
    price_min: Number(r.price_min || 0),
    price_max: Number(r.price_max || 0),
    includes_text: String(r.includes_text || '').trim(),
    ideal_for: String(r.ideal_for || '').trim(),
    notes: String(r.notes || '').trim(),
    rule_text: String(r.rule_text || '').trim(),
    active: true,
    source_sheet: String(r.source_sheet || 'catalogo_luna'),
    source_row: r.source_row || '',
    version: String(r.version || 'unknown'),
    updated_at: String(r.updated_at || ''),
  }));
const money = (v) => '$' + Number(v || 0).toLocaleString('es-CO');
const by = (category) => rows.filter(r => r.category === category);
const packages = by('package');
const domains = by('domain');
const addons = by('addon');
const ruleRows = by('rule');
const rules = ruleRows.map(r => r.rule_text).filter(Boolean);
const keys = rows.map(r => r.record_key).filter(Boolean);
if (keys.length !== new Set(keys).size) throw new Error('Catálogo inválido: record_key duplicado');
if (rows.some(r => !r.record_key || !r.sku || !r.name)) throw new Error('Catálogo inválido: record_key, sku y name son obligatorios');
if (rows.some(r => r.price_project < 0 || r.price_monthly < 0 || r.price_min < 0 || r.price_max < 0)) throw new Error('Catálogo inválido: precios negativos');
const essential = packages.find(p => p.sku === 'PKG-ESSENTIAL');
const professional = packages.find(p => p.sku === 'PKG-PROFESSIONAL');
const catalog_ready = Boolean(
  essential && professional &&
  essential.price_project > 0 &&
  professional.price_project > 0 &&
  essential.price_monthly >= 0 &&
  professional.price_monthly >= 0
);
if (!catalog_ready) throw new Error('Catálogo inválido: faltan Esencial o Profesional con precios válidos');
const package_map = Object.fromEntries(packages.map(p => [p.sku, p]));
const price_map = Object.fromEntries(packages.map(p => [p.sku, {
  project: p.price_project,
  monthly: p.price_monthly,
  project_display: money(p.price_project),
  monthly_display: money(p.price_monthly),
}]));
const package_lines = packages.map(p => [
  p.name + ': proyecto ' + money(p.price_project),
  p.price_monthly > 0 ? ('mensualidad ' + money(p.price_monthly)) : '',
  p.includes_text ? ('incluye ' + p.includes_text) : '',
  p.notes || '',
].filter(Boolean).join(' | '));
const domain_lines = domains.map(d => d.name + ': ' + money(d.price_min) + '–' + money(d.price_max));
const addon_lines = addons.map(a => a.name + ': proyecto ' + money(a.price_project) + ' (rango ' + money(a.price_min) + '–' + money(a.price_max) + ')');
const knowledge_base = [
  'CATÁLOGO COMERCIAL VIGENTE',
  'PAQUETES',
  ...package_lines,
  '',
  'DOMINIOS (siempre se cobran aparte)',
  ...domain_lines,
  '',
  'ADICIONALES',
  ...addon_lines,
  '',
  'REGLAS',
  ...rules,
].join('\n');
return [{ json: {
  source: 'luenio_catalog_staging',
  generated_at: new Date().toISOString(),
  catalog_version: rows[0]?.version || 'unknown',
  catalog_ready,
  counts: { total: rows.length, packages: packages.length, domains: domains.length, addons: addons.length, rules: rules.length },
  catalog_counts: { total: rows.length, packages: packages.length, domains: domains.length, addons: addons.length, rules: rules.length },
  packages,
  catalog_packages: package_map,
  price_map,
  catalog_price_map: price_map,
  domains,
  catalog_domains: domains,
  addons,
  catalog_addons: addons,
  rules,
  catalog_rules: rules,
  package_lines,
  domain_lines,
  addon_lines,
  knowledge_base,
  catalog_knowledge_base: knowledge_base,
} }];
